import{_ as i,o as k,c as n,a2 as u}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Sheria ya Uhakikisho wa Makazi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/45-住房保障法.md","filePath":"sw/45-住房保障法.md","lastUpdated":1789183869000}'),t={name:"sw/45-住房保障法.md"};function o(h,a,m,s,e,z){return k(),n("div",null,[...a[0]||(a[0]=[u('<h1 id="sheria-ya-uhakikisho-wa-makazi" tabindex="-1">Sheria ya Uhakikisho wa Makazi <a class="header-anchor" href="#sheria-ya-uhakikisho-wa-makazi" aria-label="Permalink to &quot;Sheria ya Uhakikisho wa Makazi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>45</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Haki ya Makazi, Makazi ya Uhakikisho, Mamlaka ya Nafasi, Mazingira Yanayofaa Kukaa, Kupinga Ubaguzi</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Makazi》 ni moja ya sheria tano za msingi za ustaarabu wa usawa wa nanga, na lengo lake ni kuhakikisha haki ya makazi ya kila kiumbe ndani ya Hengyuanzhou, kujenga mfumo wa uhakikisho wa makazi wa haki na endelevu, kutumia teknolojia ya mamlaka ya nafasi kutoa nafasi ya makazi inayofaa kwa kila kabila, na kuzuia ubaguzi na mauaji katika sekta ya makazi.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Uhakikisho wa Makazi</td><td>Kila kiumbe ana haki ya kupata nafasi ya makazi inayofaa, serikali na ustaarabu wana jukumu la kuhakikisha mahitaji ya msingi ya makazi</td></tr><tr><td>Kanuni ya Kipaumbele cha Manufaa ya Umma</td><td>Makazi ni kwanza mahitaji ya msingi ya maisha, sio bidhaa ya ubaguzi, makazi ya uhakikisho yana sifa ya manufaa ya umma</td></tr><tr><td>Kanuni ya Ufanisi wa Nafasi</td><td>Kutumia teknolojia ya mamlaka ya nafasi kuboresha ufanisi wa matumizi ya nafasi na kupanua nafasi inayofaa kukaa</td></tr><tr><td>Kanuni ya Uwezo wa Kukabiliana na Makabila</td><td>Kutoa nafasi ya makazi inayofaa kwa tabia za kibaolojia na tabia za maisha za makabila tofauti</td></tr><tr><td>Kanuni ya Mazingira Yanayofaa Kukaa</td><td>Nafasi ya makazi inapaswa kuwa na mazingira mazuri ya ikolojia, miundombinu ya msingi, na huduma za umma</td></tr><tr><td>Kanuni ya Kupinga Ubaguzi</td><td>Kukataza ubaguzi wa makazi kama kipimo, kuzuia makazi kuwa zana ya mauaji ya mali</td></tr></tbody></table><h2 id="_2-uhakikisho-wa-kisheria-wa-haki-ya-makazi" tabindex="-1">2. Uhakikisho wa Kisheria wa Haki ya Makazi <a class="header-anchor" href="#_2-uhakikisho-wa-kisheria-wa-haki-ya-makazi" aria-label="Permalink to &quot;2. Uhakikisho wa Kisheria wa Haki ya Makazi&quot;">​</a></h2><p>Sheria hii inabainisha wazi kwamba haki ya makazi ni haki ya msingi inayotolewa kwa kila kiumbe na Katiba ya Usawa, ikiwa ni pamoja na:</p><ol><li><strong>Haki ya Msingi ya Makazi</strong>: Kila kiumbe ana haki ya kupata nafasi ya makazi isiyochini ya kiwango cha chini, na kiwango cha chini kinabainishwa kulingana na ukubwa wa mwili na mahitaji ya maisha ya kabila.</li><li><strong>Haki ya Ombi la Makazi ya Uhakikisho</strong>: Viumbe vilivyo vya kufuata sheria vina haki ya kuomba makazi ya uhakikisho, na masharti ya ombi na vigezo vya usambazaji ni wazi na wazi.</li><li><strong>Haki ya Usalama wa Makazi</strong>: Nafasi ya makazi inapaswa kutimiza viwango vya usalama, na nyumba za hatari na nafasi zisizofaa kukaa hazifai kukodiwa au kusambazwa.</li><li><strong>Haki ya Uthabiti wa Makazi</strong>: Wakazi wa makazi ya uhakikisho, wanapotimiza masharti, hufurahia haki ya makazi thabiti na hawafai kufukuzwa kwa hiari.</li><li><strong>Haki ya Mazingira ya Makazi</strong>: Wakazi wana haki ya kupata hewa safi, vyanzo vya maji, na mazingira mazuri ya karibu, na wana haki ya kuomba malalamiko kuhusu uchafuzi wa mazingira.</li><li><strong>Haki ya Marekebisho ya Makazi</strong>: Wakazi wana haki ya kufanya marekebisho yanayofaa katika nafasi ya makazi, kwa masharti ya kuwa havathiri usalama wa jengo na haki za wengine.</li></ol><h2 id="_3-mfumo-wa-uhakikisho-wa-makazi" tabindex="-1">3. Mfumo wa Uhakikisho wa Makazi <a class="header-anchor" href="#_3-mfumo-wa-uhakikisho-wa-makazi" aria-label="Permalink to &quot;3. Mfumo wa Uhakikisho wa Makazi&quot;">​</a></h2><p>Mfumo wa uhakikisho wa makazi wa ustaarabu wa usawa wa nanga umegawanyika katika aina tatu za makazi, na kufunika viwango tofauti vya mahitaji:</p><table tabindex="0"><thead><tr><th>Aina</th><th>Jina</th><th>Kipimo cha Uhakikisho</th><th>Njia ya Usambazaji</th><th>Kodi/Bei</th></tr></thead><tbody><tr><td>Aina ya kwanza</td><td>Makazi ya Kodi ya Umma</td><td>Vikundi vya kipato cha chini, wanaofanya mazoezi wa awali, wahamiaji wapya</td><td>Mfumo wa ombi na hakiki, usambazaji wa foleni</td><td>Kodi ndogo ya ishara</td></tr><tr><td>Aina ya pili</td><td>Makazi ya Umiliki wa Pamoja</td><td>Vikundi vya kipato cha kati, wanaofanya mazoezi wa kiwango cha kati</td><td>Mfumo wa ombi na hakiki, usambazaji wa bahati nasibu</td><td>Chini ya bei ya soko, umiliki wa pamoja kati ya mtu binafsi na serikali</td></tr><tr><td>Aina ya tatu</td><td>Makazi ya Biashara</td><td>Vikundi vya kipato cha juu, wanaofanya mazoezi ya juu</td><td>Biashara ya soko</td><td>Bei ya soko, chini ya udhibiti</td></tr></tbody></table><p>Zaidi ya hayo, teknolojia ya kusonga nafasi inatumika kujenga &quot;Maeneo ya Makazi ya Nafasi Iliyosongezwa&quot;: ndani ya nafasi ya kimwili iliyo na mdudu, teknolojia ya kusonga nafasi inapanua eneo la makazi, na kutoa nafasi zaidi za makazi kwa maeneo yenye msongamano mkubwa. Maeneo ya makazi ya nafasi iliyosongezwa lazima yapite tathmini ya usalama ili kuhakikisha uthabiti wa nafasi.</p><h2 id="_4-uwezo-wa-kukabiliana-na-makabila-wa-makazi" tabindex="-1">4. Uwezo wa Kukabiliana na Makabila wa Makazi <a class="header-anchor" href="#_4-uwezo-wa-kukabiliana-na-makabila-wa-makazi" aria-label="Permalink to &quot;4. Uwezo wa Kukabiliana na Makabila wa Makazi&quot;">​</a></h2><p>Kwa mahitaji maalum ya makazi ya makabila tofauti ndani ya Hengyuanzhou, sheria hii inaweka mfumo wa uwezo wa kukabiliana na makabila wa makazi:</p><ul><li><strong>Makabila ya Maji</strong>: Kutoa nafasi ya makazi chini ya maji au makazi ya amfibia ya maji-na-dongo, zikiwa na mfumo wa mzunguko wa maji na utunzaji wa ubora wa maji.</li><li><strong>Makabila ya Kuruka</strong>: Kutoa nafasi ya makazi kwenye urefu wa juu au makazi yenye jukwaa la kutua na kuruka, zikiwa na usimamizi wa trafiki ya angani.</li><li><strong>Maisha ya Nishati</strong>: Kutoa nafasi ya makazi yenye msongamano wa nishati unaofaa, zikiwa na kifaa cha uthabiti wa nishati.</li><li><strong>Makabila ya Kubwa</strong>: Kutoa nafasi ya makazi ya kiwango kikubwa, na muundo wa jengo umeimarishwa kwa kima cha pekee.</li><li><strong>Makabila ya Ndogo</strong>: Kutoa maeneo ya makazi ya ndogo, yakiwa na njia za kubadilisha kiwango na vifaa maalum.</li></ul><p>Viwango vya uwezo wa kukabiliana na makabila wa makazi vinaandaliwa pamoja na idara inayohusiana ya makazi na wawakilishi wa kila kabila, na vinasasishwa mara kwa mara.</p><h2 id="_5-ujenzi-na-usimamizi-wa-makazi" tabindex="-1">5. Ujenzi na Usimamizi wa Makazi <a class="header-anchor" href="#_5-ujenzi-na-usimamizi-wa-makazi" aria-label="Permalink to &quot;5. Ujenzi na Usimamizi wa Makazi&quot;">​</a></h2><ul><li><strong>Mpango wa Ujenzi wa Makazi</strong>: Serikali inaandaa mpango wa ujenzi wa makazi kulingana na ukuaji wa wakazi na hali ya uhamiaji, na kuhakikisha usawa wa ugavi na mahitaji ya makazi.</li><li><strong>Viwango vya Ujenzi</strong>: Ujenzi wa makazi ya uhakikisho lazima utimize viwango vya usalama, mazingira, yanayofaa kukaa, na kukataza kupunguza ubora wa ujenzi.</li><li><strong>Usimamizi wa Mali</strong>: Maeneo ya makazi yanatumia muundo unaounganisha usimamizi wa kujitegemea na usimamizi wa kitaaluma wa mali, na wakazi wana haki ya kushiriki katika maamuzi ya usimamizi wa mali.</li><li><strong>Matengenezo ya Makazi</strong>: Matengenezo ya makazi ya uhakikisho ni jukumu la taasisi ya usimamizi wa makazi, na fedha za matengenezo zinatokana na akiba ya umma.</li><li><strong>Mfumo wa Kutokea</strong>: Wakati kipato au kiwango cha mazoezi cha mkazi wa makazi ya uhakikisho kikipita kiwango cha uhakikisho, anapaswa kutokea kwenye makazi ya uhakikisho au kuzibadilisha kuwa makazi ya biashara, na nafasi ya mpito inayofaa inatolewa.</li></ul><h2 id="_6-kupinga-ubaguzi-na-usimamizi" tabindex="-1">6. Kupinga Ubaguzi na Usimamizi <a class="header-anchor" href="#_6-kupinga-ubaguzi-na-usimamizi" aria-label="Permalink to &quot;6. Kupinga Ubaguzi na Usimamizi&quot;">​</a></h2><p>Ili kuzuia ubaguzi na mauaji katika sekta ya makazi, sheria hii inaweka hatua zifuatazo za usimamizi:</p><ol><li>Kupunguza idadi ya makazi ya biashara ambayo mtu binafsi anaweza kumiliki, na kuchukua ushuru wa makazi wa endelevu kwa kiwango kilichozidi kikomo.</li><li>Kukataza kukodiwa upya na kuuzwa upya wa makazi ya uhakikisho, na wanaofanya makosa watachukuliwa kweli ya uhakikisho na makazi yatarudishwa.</li><li>Kujenga mfumo wa wazi wa taarifa za biashara za makazi, ili kuzuia shughuli za kisanduku cheusi na udhibiti wa bei.</li><li>Kutekeleza usimamizi wa kweli na usimamizi wa fedha kwa watengenezaji wa makazi, ili kuzuia ujenzi usio kamili na udanganyifu.</li><li>Kuanzisha mfumo wa malalamiko ya makazi na kutatua mizozo, ili kuhakikisha haki za kisheria za wakazi.</li></ol><h2 id="_7-wajibu-wa-kisheria" tabindex="-1">7. Wajibu wa Kisheria <a class="header-anchor" href="#_7-wajibu-wa-kisheria" aria-label="Permalink to &quot;7. Wajibu wa Kisheria&quot;">​</a></h2><p>Shughuli zinazovunja masharti ya sheria hii zitabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ul><li>Kusambaza makazi ya uhakikisho kwa kuvunja sheria, kuamriwa kurekebisha na kupigwa faini mtu anayehusika.</li><li>Kukodiwa upya, kuuzwa upya makazi ya uhakikisho, kuchukuliwa kweli ya uhakikisho, kurudishwa makazi na kupigwa faini.</li><li>Watengenezaji wanaopunguza ubora wa ujenzi, kuamriwa kujenga upya na kupigwa faini, katika visa vizito kweli inakatiwa.</li><li>Ubaguzi wa makazi, kuchukua ushuru wa juu wa ubaguzi na kupigwa faini.</li><li>Kukodi nyumba za hatari kusababisha uharibifu kwa wakazi, kubeba wajibu wa fidia, katika visa vizito wajibu wa jinai unafuatiliwa.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Makazi》 ni utekelezaji wa dhana ya &quot;kila mtu ana njia&quot; ya ustaarabu wa usawa wa nanga katika sekta ya makazi. Kupitia kujenga mfumo wa uhakikisho wa makazi uliogawanyika, kutumia teknolojia ya mamlaka ya nafasi kupanua nafasi ya makazi, kutoa uwezo wa kukabiliana na mahitaji ya makazi ya makabila, na kupiga vita ubaguzi wa makazi, inahakikisha kwamba kila kiumbe anaweza kuwa na nyumba salama, inayofaa, thabiti, na kutoa uhakikisho wa makazi kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>39-住房与环境保障 (Uhakikisho wa Makazi na Mazingira)</li><li>13-空间法理调度体系详解 (Maelezo ya Kina ya Mfumo wa Mamlaka ya Nafasi)</li><li>46-环境保护法 (Sheria ya Kulinda Mazingira)</li></ul>',29)])])}const y=i(t,[["render",o]]);export{l as __pageData,y as default};
